<?php
include_once 'db.php';
$inicio = (string)($_GET['inicio'] ?? date('Y-m-01')); $fim = (string)($_GET['fim'] ?? date('Y-m-t'));
if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $inicio)) $inicio = date('Y-m-01'); if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $fim)) $fim = date('Y-m-t'); if ($fim < $inicio) [$inicio, $fim] = [$fim, $inicio];
$permitidos = ['pix','dinheiro','cartao_debito','cartao_credito']; $pagamentos = array_values(array_intersect($permitidos, (array)($_GET['pagamentos'] ?? []))); if (empty($pagamentos)) $pagamentos = $permitidos;
$ids = array_filter(array_map('strval', (array)($_GET['vendas'] ?? []))); $cartoesJuntos = ($_GET['cartoes_juntos'] ?? '') === '1';
$vendas = array_values(array_filter(listarVendasLocais(), static function ($v) use ($inicio,$fim,$pagamentos,$ids) { $data=substr((string)($v['realizada_em']??''),0,10); $p=(string)($v['forma_pagamento']??''); $id=(string)($v['registro_local_id']??''); return $data >= $inicio && $data <= $fim && in_array($p,$pagamentos,true) && (empty($ids)||in_array($id,$ids,true)); }));
usort($vendas, static fn($a,$b)=>strcmp((string)($a['realizada_em']??''),(string)($b['realizada_em']??'')));
$rotulos=['pix'=>'PIX','dinheiro'=>'Dinheiro','cartao_debito'=>'Cartão de débito','cartao_credito'=>'Cartão de crédito','cartoes'=>'Cartões - crédito e débito']; $grupos=[];
foreach($vendas as $v){$p=(string)($v['forma_pagamento']??'');$grupo=$cartoesJuntos&&in_array($p,['cartao_debito','cartao_credito'],true)?'cartoes':$p;$grupos[$grupo][]=$v;} $ordem=['pix','dinheiro','cartoes','cartao_debito','cartao_credito'];
?>
