<?php foreach($grupos[$chave] as $venda):$cliente=(array)($venda['cliente_detalhes']??[]);if(empty($cliente)&&!empty($venda['cliente_id'])){$clienteApi=buscarCliente($venda['cliente_id']);if(is_array($clienteApi)&&!isset($clienteApi['error']))$cliente=$clienteApi;}?><section class="venda"><div class="venda-titulo"><span><?=htmlspecialchars($venda['cliente_nome']??'Cliente')?> - <?=htmlspecialchars(date('d/m/Y H:i',strtotime((string)$venda['realizada_em'])))?></span><span><?=htmlspecialchars($rotulos[$venda['forma_pagamento']]??$venda['forma_pagamento'])?><?=!empty($venda['bandeira_cartao'])?' - '.htmlspecialchars(strtoupper($venda['bandeira_cartao'])):''?></span></div><div class="grade"><div class="cliente"><strong>CPF:</strong> <?=htmlspecialchars($cliente['cpf']??$venda['cliente_cpf']??'')?> &nbsp; <strong>RG:</strong> <?=htmlspecialchars($cliente['rg']??'')?><br><strong>WhatsApp:</strong> <?=htmlspecialchars($cliente['whatsapp']??'')?> &nbsp; <strong>Telefone:</strong> <?=htmlspecialchars($cliente['telefone_secundario']??'')?><br><strong>E-mail:</strong> <?=htmlspecialchars($cliente['email']??'')?><br><strong>Endereço:</strong> <?=htmlspecialchars(implode(', ',array_filter([$cliente['rua']??'',$cliente['numero']??'',$cliente['bairro']??'',$cliente['cidade']??'',$cliente['cep']??''])))?><br><?php if(!empty($cliente['complemento'])):?><strong>Complemento:</strong> <?=htmlspecialchars($cliente['complemento'])?><br><?php endif;?><?php if(!empty($cliente['preferencias'])):?><strong>Observações:</strong> <?=htmlspecialchars($cliente['preferencias'])?><?php endif;?></div><div><table><thead><tr><th>Vestido / operação</th><th class="valor">Valor</th></tr></thead><tbody><?php foreach(($venda['itens']??[]) as $item):?><tr><td><?=htmlspecialchars($item['produto_nome']??('Produto #'.($item['produto_id']??'')))?> - <?=htmlspecialchars(strtoupper((string)($item['tipo']??'')))?></td><td class="valor">R$ <?=number_format((float)($item['preco']??0),2,',','.')?></td></tr><?php endforeach;?></tbody></table><?php if(!empty($venda['data_retirada'])):?><p><strong>Retirada:</strong> <?=date('d/m/Y',strtotime($venda['data_retirada']))?> - <strong>Devolução:</strong> <?=date('d/m/Y',strtotime($venda['data_devolucao']))?></p><?php endif;?><p><strong>Subtotal:</strong> R$ <?=number_format((float)($venda['subtotal']??0),2,',','.')?> - <strong>Desconto:</strong> R$ <?=number_format((float)($venda['desconto_valor']??0),2,',','.')?> - <span class="total">Total: R$ <?=number_format((float)($venda['valor_final']??0),2,',','.')?></span></p></div></div></section><?php endforeach;?><?php endforeach;?><footer>TOA TOA Moda Festa - Relatório interno de vendas</footer></div></body></html>
